import React from "react";
import { Audio, Sequence, staticFile } from "remotion";

export type SfxName =
  | "cut"
  | "shutter"
  | "pop1"
  | "pop2"
  | "pop3"
  | "key-down"
  | "key-up"
  | "type1"
  | "type2"
  | "type3"
  | "type4"
  | "type5"
  | "type6"
  | "mouse"
  | "swish"
  | "riser"
  | "riser-short"
  | "cut1" | "cut2" | "cut3" | "cut4"
  | "note1" | "note2" | "note3" | "note4" | "note5" | "note6" | "note7" | "note8";

/**
 * Plays a sound effect from public/sfx (generated by the skill's scripts/sfx.mjs) at a local frame.
 * Put it next to the visual it belongs to, so picture and sound can't drift apart.
 */
export const Sfx: React.FC<{ name: SfxName; at: number; volume?: number }> = ({ name, at, volume = 1 }) => (
  <Sequence from={Math.round(at)} durationInFrames={name.startsWith("riser") ? 70 : 18} layout="none" name={`sfx:${name}`}>
    <Audio src={staticFile(`sfx/${name}.wav`)} volume={volume} />
  </Sequence>
);

/** Typing sounds for `count` characters starting at `at`, one every `every` frames (varied samples). */
export const TypingSfx: React.FC<{ at: number; count: number; every: number; volume?: number; skip?: (i: number) => boolean }> = ({
  at,
  count,
  every,
  volume = 0.8,
  skip,
}) => (
  <>
    {new Array(count).fill(0).map((_, i) =>
      skip?.(i) ? null : (
        <Sfx key={i} name={`type${((i * 7 + 3) % 6) + 1}` as SfxName} at={at + i * every} volume={volume * (0.75 + ((i * 13) % 5) * 0.06)} />
      ),
    )}
  </>
);
